protected_prefixes=['src','public','functions','wrangler.jsonc','astro.config.mjs','.github'];diff=subprocess.check_output(['git','diff',BASE,'--name-only','--',*protected_prefixes],text=True).splitlines();assert not diff,diff
r={'status':'PUBLIC_TRACKED_CONTENT_UNCHANGED','base':BASE,'publicProtectedDiff':diff,'sourceHashes':sources,'preexistingRecoveryScriptsAndR1BReportsUnchanged':True,'protected':['6H/7B source files','R3 runtime/API and reported 47 clips','2D fallbacks','modo-imersivo','404/Tetris','curiosidades','Hsin','Shorekeeper','Phrolova','Cloudflare Access/R2/infra configuration'],'r3BinaryRecounted':False,'r3Note':'Reported 47 clips inherited; protected binary not freshly readable (403 in previous retrieval). No remote storage/auth changes.','mainModifiedByThisWork':False,'limits':['Tracked content comparison; not a fresh R3 binary access/recount or proof of remote main activity by others']};p=pathlib.Path('docs/sophia/adornments-r1c/results/r1c-preservation.json');p.write_text(json.dumps(r,indent=2)+'\n');print(r['status'])
